content[194]=[[["June goes to the shop on Saturday.", "June vai à loja no sábado."], ["She buys a bottle of water.", "Ela compra uma garrafa de água."], ["She gets a kilo of oranges.", "Ela pega um quilo de laranjas."], ["She also buys a bag of salt.", "Ela também compra um pacote de sal."], ["At the end she takes a piece of cake.", "No fim ela pega um pedaço de bolo."]], [["What do you need today?", "De que você precisa hoje?"], ["I need a bottle of juice.", "Preciso de uma garrafa de suco."], ["Do you want a kilo of rice?", "Você quer um quilo de arroz?"], ["No, a bag of rice is enough.", "Não, um pacote de arroz basta."], ["Is that all?", "É só isso?"], ["No, a piece of cheese too, please.", "Não, um pedaço de queijo também, por favor."], ["How big is the piece?", "Qual o tamanho do pedaço?"], ["It is about one hand big.", "É mais ou menos do tamanho de uma mão."]], ["Palavra bottle", "Diga BA-tel; o tt soa como um d rápido nos EUA.", ["bottle", "A bottle of water."]], ["I want a ___ of water.", "bottle", "glass bottle", "Quero uma garrafa de água.", "Depois de a, use a medida e of: a bottle of."]];
