content[199]=[[["Lia takes a basket to the market.", "Lia leva uma cesta ao mercado."], ["She needs a kilo of oranges.", "Ela precisa de um quilo de laranjas."], ["How much are they?", "Quanto custam?"], ["Three dollars a kilo.", "Três dólares o quilo."], ["She pays and gets the receipt.", "Ela paga e pega o recibo."]], [["How much are the oranges?", "Quanto custam as laranjas?"], ["They are three dollars a kilo.", "Custam três dólares o quilo."], ["How many kilos do you need?", "De quantos quilos você precisa?"], ["I need two kilos, please.", "Preciso de dois quilos, por favor."], ["Is there any change for ten dollars?", "Tem troco para dez dólares?"], ["Yes, here is your change.", "Sim, aqui está seu troco."], ["Do you want a receipt?", "Você quer o recibo?"], ["Yes, please. I need it for my list.", "Sim, por favor. Preciso dele para minha lista."]], ["Palavra receipt", "O p não soa: ri-SIIT.", ["receipt", "Here is your receipt."]], ["How ___ is the cheese?", "much", "many", "Quanto custa o queijo?", "Para preço, use How much."]];
