content[203]=[[["Peg finds a key on the table.", "Peg acha uma chave na mesa."], ["Whose key is this?", "De quem é esta chave?"], ["It is Tina’s key.", "É a chave da Tina."], ["Tina says the key is hers.", "Tina diz que a chave é dela."], ["Peg says the lamp is mine.", "Peg diz que o abajur é meu."]], [["Whose lamp is this?", "De quem é este abajur?"], ["It is mine.", "É meu."], ["Whose keys are these?", "De quem são estas chaves?"], ["They are yours, I think.", "São suas, eu acho."], ["Is this bag hers?", "Esta bolsa é dela?"], ["No, hers is the red bag.", "Não, a dela é a bolsa vermelha."], ["Are these books his?", "Estes livros são dele?"], ["No, they are not his. They are mine.", "Não, não são dele. São meus."]], ["/uː/ em whose", "Arredonde bem os lábios: whose soa como hooz, igual a who com z no fim.", ["whose", "Whose book is this?"]], ["This lamp is not yours. It is ___.", "mine", "me", "Este abajur não é seu. É meu.", "Mine substitui my + substantivo; me não serve."]];
