content[205]=[[["Lou has a baby cousin.", "Lou tem uma prima bebê."], ["The baby is one year old.", "O bebê tem um ano."], ["Lou is twelve years old.", "Lou tem doze anos."], ["His other cousin is nine.", "O outro primo dele tem nove."], ["They are all at Lou’s house for a party.", "Todos estão na casa do Lou para uma festa."]], [["How old is your cousin?", "Quantos anos tem o seu primo?"], ["She is eight years old.", "Ela tem oito anos."], ["How old are you?", "Quantos anos você tem?"], ["I am thirty-one.", "Tenho trinta e um."], ["How old is the baby?", "Quantos anos tem o bebê?"], ["He is only ten months old.", "Ele tem só dez meses."], ["So your sister is twenty-five?", "Então a sua irmã tem vinte e cinco?"], ["Yes, she is twenty-five today.", "Sim, ela faz vinte e cinco hoje."]], ["/θ/ em thirty", "Ponha a língua entre os dentes e solte o ar sem voz: thirty não começa com t nem com s.", ["thirty", "I am thirty today."]], ["How old ___ your cousin?", "is", "has", "Quantos anos o seu primo tem?", "Em inglês a idade usa o verbo be, não have."]];
