content[207]=[[["Tina looks at an apartment in the city.", "Tina visita um apartamento na cidade."], ["The kitchen is clean and bright.", "A cozinha é limpa e clara."], ["The street is very noisy.", "A rua é muito barulhenta."], ["The sofa is old, but the bed is new.", "O sofá é velho, mas a cama é nova."], ["She wants a quiet house, so she says no.", "Ela quer uma casa silenciosa, então diz não."]], [["Is the house big or small?", "A casa é grande ou pequena?"], ["It is small, but it is new.", "É pequena, mas é nova."], ["Is the sofa old?", "O sofá é velho?"], ["Yes, but it is very good.", "Sim, mas é muito bom."], ["Is the street noisy?", "A rua é barulhenta?"], ["Yes, it is noisy at night.", "Sim, é barulhenta à noite."], ["So the kitchen is new and clean?", "Então a cozinha é nova e limpa?"], ["Yes, new and very clean.", "Sim, nova e muito limpa."]], ["Vogal longa em clean", "Estique o som i: clean é lon-go, bem diferente do curto de in.", ["clean", "The room is clean."]], ["The windows are ___.", "big", "bigs", "As janelas são grandes.", "Adjetivos não mudam no plural."]];
