stories[209]=["Uma festa na casa do Nico", "Nico has a big family and a small house.~Nico tem uma família grande e uma casa pequena.|His grandmother has a party today.~A avó dele faz uma festa hoje.|Nico’s mother has a big cake in the kitchen.~A mãe do Nico tem um bolo grande na cozinha.|There are ten people in the house.~Há dez pessoas na casa.|Nico finds a phone under the sofa.~Nico acha um telefone embaixo do sofá.|Whose phone is this? It is his cousin’s.~De quem é este telefone? É do primo dele.|The cousin is nine years old.~O primo tem nove anos.|The house is noisy, but everyone is happy.~A casa é barulhenta, mas todos estão felizes.|Their house is old, but it is very clean.~A casa deles é velha, mas é muito limpa.|Nico loves his big family.~Nico adora a família grande dele."];
plans[210]={"title": "Ligando para a Ava", "file": "photo-coast-1.webp", "grammar": "It is + clima", "goal": "Descreva o tempo com It is + sunny, rainy, hot ou cold.", "words": [["sunny", "ensolarado"], ["rainy", "chuvoso"], ["today", "hoje"], ["city", "cidade"]]};
content[210]=[[["Ravi calls Ava in Boston.", "Ravi liga para a Ava em Boston."], ["It is sunny in Boston today.", "Está ensolarado em Boston hoje."], ["It is rainy at Ravi’s house.", "Está chovendo na casa do Ravi."], ["It is hot there, so Ava has ice cream.", "Está quente lá, então a Ava toma sorvete."], ["Ravi has tea because it is cold.", "Ravi toma chá porque está frio."]], [["Is it sunny today?", "Está ensolarado hoje?"], ["Yes, it is sunny and hot.", "Sim, está ensolarado e quente."], ["Is it rainy at your house?", "Está chovendo na sua casa?"], ["Yes, it is rainy again.", "Sim, está chovendo de novo."], ["Is it cold in the city?", "Está frio na cidade?"], ["No, it is not cold.", "Não, não está frio."], ["So it is sunny there?", "Então está ensolarado aí?"], ["Yes, it is sunny all day.", "Sim, está ensolarado o dia todo."]], ["/ʌ/ em sunny", "Abra a boca pouco e solte um a curto: SUN-ny, não san nem son.", ["sunny", "It is sunny today."]], ["___ rainy today.", "It is", "It has", "Está chovendo hoje.", "Para o clima, use it is, não it has."]];
