content[212]=[[["Ben looks at a photo of the class.", "Ben olha uma foto da turma."], ["Ava is wearing a blue jacket.", "Ava está usando uma jaqueta azul."], ["Noah is wearing a white shirt.", "Noah está usando uma camisa branca."], ["Lia is wearing jeans and a red hat.", "Lia está usando jeans e um chapéu vermelho."], ["Ben is laughing in the photo.", "Ben está rindo na foto."]], [["What are you wearing today?", "O que você está vestindo hoje?"], ["I am wearing a black jacket.", "Estou com uma jaqueta preta."], ["Is it new?", "Ela é nova?"], ["Yes, I am wearing it for the first time.", "Sim, estou usando pela primeira vez."], ["What is Ava wearing?", "O que a Ava está vestindo?"], ["She is wearing a yellow shirt.", "Ela está com uma camisa amarela."], ["So you are wearing black today?", "Então você está de preto hoje?"], ["Yes, and I am wearing jeans too.", "Sim, e estou de jeans também."]], ["Final -ing em wearing", "Termine com um n nasal suave, sem soltar o g: weari-ng.", ["wearing", "I am wearing a hat."]], ["I ___ a jacket today.", "am wearing", "wear", "Estou usando uma jaqueta hoje.", "Para o que acontece agora, use am + verbo com -ing."]];
