content[213]=[[["Peg stands at the door.", "Peg está parada na porta."], ["Lou asks if she is wearing a hat.", "Lou pergunta se ela está de chapéu."], ["She is not wearing a hat today.", "Hoje ela não está de chapéu."], ["Lou gives her a warm scarf.", "Lou dá a ela um cachecol quente."], ["Peg is wearing the scarf now.", "Agora a Peg está com o cachecol."]], [["Are you wearing a scarf today?", "Você está de cachecol hoje?"], ["Yes, I am. It is warm.", "Sim, estou. É quentinho."], ["Is Lou wearing a hat?", "O Lou está de chapéu?"], ["No, he is not. He has a cap.", "Não, não está. Ele está com boné."], ["Are they wearing coats?", "Eles estão de casaco?"], ["Yes, they are. It is cold.", "Sim, estão. Está frio."], ["Is she wearing a scarf too?", "Ela também está de cachecol?"], ["Yes, she is. It is red.", "Sim, está. É vermelho."]], ["Respostas curtas fracas", "Em Yes, I am, o am é forte no fim; em No, he is not, destaque o not.", ["am", "Yes, I am."]], ["___ you wearing a hat?", "Are", "Do", "Você está usando um chapéu?", "A pergunta no present continuous começa com be: Are you wearing…?"]];
