content[216]=[[["Noah needs a sweater for winter.", "Noah precisa de um suéter para o inverno."], ["His mother wants to go to the store.", "A mãe dele quer ir à loja."], ["Noah likes the gray sweater.", "Noah gosta do suéter cinza."], ["He also wants a cap.", "Ele também quer um boné."], ["They buy the sweater and the cap.", "Eles compram o suéter e o boné."]], [["Which clothes do you need today?", "Quais roupas você precisa hoje?"], ["I need a warm sweater.", "Preciso de um suéter quente."], ["Do you want a cap too?", "Você quer um boné também?"], ["Yes, I like the blue cap.", "Sim, gosto do boné azul."], ["What does Ben want?", "O que o Ben quer?"], ["He wants a long coat.", "Ele quer um casaco longo."], ["Do you like this gray sweater?", "Você gosta deste suéter cinza?"], ["Yes, I like it, and I need it.", "Sim, gosto e preciso dele."]], ["/w/ em sweater", "Comece com os lábios arredondados: sweater tem um w depois do s.", ["sweater", "I need a sweater."]], ["Noah ___ a new sweater.", "needs", "need", "Noah precisa de um suéter novo.", "Com nomes no singular, o verbo leva -s: needs."]];
