content[221]=[[["Noah works in an office downtown.", "Noah trabalha em um escritório no centro."], ["His sister Tina works at a bank.", "A irmã dele, Tina, trabalha em um banco."], ["She works with money all day.", "Ela trabalha com dinheiro o dia todo."], ["Their friend Peg works at a factory.", "A amiga deles, Peg, trabalha em uma fábrica."], ["They eat lunch together on Fridays.", "Eles almoçam juntos às sextas."]], [["Where does Noah work?", "Onde o Noah trabalha?"], ["He works in an office.", "Ele trabalha em um escritório."], ["And where does Tina work?", "E onde a Tina trabalha?"], ["She works at a bank.", "Ela trabalha em um banco."], ["Where does Peg work?", "Onde a Peg trabalha?"], ["She works at a factory near the river.", "Ela trabalha em uma fábrica perto do rio."], ["Where do you work, Lia?", "Onde você trabalha, Lia?"], ["I work at a small bakery.", "Trabalho em uma padaria pequena."]], ["S final em works", "Em works, o s no fim soa como /s/ e não como z; solte o ar devagar.", ["works", "She works here."]], ["She ___ at a school.", "works", "work", "Ela trabalha em uma escola.", "Com he ou she, o verbo no presente leva -s."]];
