content[229]=[[["Tina has a busy day at the office.", "Tina tem um dia cheio no escritório."], ["She starts at eight and has a meeting.", "Ela começa às oito e tem uma reunião."], ["At noon, she has to eat lunch fast.", "Ao meio-dia, ela tem que almoçar rápido."], ["Why? Because she has a class at one.", "Por quê? Porque ela tem aula à uma."], ["She works and studies, so she is tired.", "Ela trabalha e estuda, por isso está cansada."]], [["What do you do, Tina?", "O que você faz, Tina?"], ["I work in an office and study at night.", "Trabalho em um escritório e estudo à noite."], ["Do you have a busy day?", "Você tem um dia cheio?"], ["Yes, I have to work until five.", "Sim, tenho que trabalhar até as cinco."], ["Why do you study at night?", "Por que você estuda à noite?"], ["Because I want a better job.", "Porque quero um emprego melhor."], ["Does Ravi study too?", "O Ravi também estuda?"], ["Yes, he does. He works at a school.", "Sim. Ele trabalha em uma escola."]], ["Som /ʌ/ em lunch", "Abra pouco a boca e mantenha a língua relaxada, como um a curto e fechado.", ["lunch", "We have lunch at noon."]], ["Tina ___ in an office.", "works", "work", "Tina trabalha em um escritório.", "Com she ou um nome no singular, o verbo leva -s."]];
