content[232]=[[["Lia is lost in a big city.", "Lia está perdida em uma cidade grande."], ["She asks, \"How do I get to the museum?\"", "Ela pergunta: \"Como chego ao museu?\""], ["A woman says, \"Go straight, then turn left at the traffic light.\"", "Uma mulher diz: \"Siga em frente e vire à esquerda no semáforo.\""], ["Then Lia walks two blocks.", "Depois Lia anda dois quarteirões."], ["She says thank you and goes on.", "Ela agradece e segue em frente."]], [["Excuse me, how do I get to the museum?", "Com licença, como chego ao museu?"], ["First, go straight for two blocks.", "Primeiro, siga em frente por dois quarteirões."], ["And then?", "E depois?"], ["Then turn left at the traffic light.", "Depois vire à esquerda no semáforo."], ["Is it far from there?", "Fica longe de lá?"], ["No, it is on the right.", "Não, fica à direita."], ["So I go straight, then turn left?", "Então sigo em frente e viro à esquerda?"], ["Yes, that is right.", "Sim, isso mesmo."]], ["Ritmo de How do I", "Em how do I get to, as palavras pequenas ficam fracas e get e to se ligam: get-tə.", ["museum", "How do I get to the museum?"]], ["___ do I get to the museum?", "How", "What", "Como eu chego ao museu?", "Para pedir o caminho, use How do I get to…?"]];
