content[264]=[[["Tina wants to study for a test.", "Tina quer estudar para uma prova."], ["She studied at the library for two hours.", "Ela estudou na biblioteca por duas horas."], ["Then she stopped and called Lou.", "Depois ela parou e ligou para o Lou."], ["Lou carried two cups of tea.", "Lou levou duas xícaras de chá."], ["They want to stop and rest.", "Eles querem parar e descansar."]], [["Who studied with you today?", "Quem estudou com você hoje?"], ["Tina studied with me.", "A Tina estudou comigo."], ["Is it hard to study here?", "É difícil estudar aqui?"], ["No, it is quiet.", "Não, é tranquilo."], ["Who stopped at the cafe?", "Quem parou no café?"], ["Lou stopped there and carried tea.", "O Lou parou lá e levou chá."], ["Who tried the new tea?", "Quem provou o chá novo?"], ["Tina tried it and liked it.", "A Tina provou e gostou."]], ["Final -ed como /ɪd/", "Depois de t ou d, o -ed vira uma sílaba extra: wanted = WAN-tid.", ["wanted", "He wanted tea."]], ["She ___ at the library.", "studied", "studyed", "Ela estudou na biblioteca.", "Verbo terminado em consoante + y troca o y por ied."]];
