content[265]=[[["Ravi went to the market with June.", "Ravi foi ao mercado com a June."], ["They saw many fruits and fish.", "Eles viram muitas frutas e peixes."], ["June had a small red bag.", "A June tinha uma bolsa vermelha pequena."], ["They ate bread at a little table.", "Eles comeram pão em uma mesinha."], ["They went home at noon.", "Eles foram para casa ao meio-dia."]], [["Who went to the market?", "Quem foi ao mercado?"], ["Ravi and June went.", "O Ravi e a June foram."], ["Who saw the fish?", "Quem viu os peixes?"], ["I saw it. It was big.", "Eu vi. Era grande."], ["Who had a bag?", "Quem tinha uma bolsa?"], ["June had a red bag.", "A June tinha uma bolsa vermelha."], ["Who ate the bread?", "Quem comeu o pão?"], ["We ate it at noon.", "Nós comemos ao meio-dia."]], ["O /ɛ/ em went", "Boca meio aberta, como em “pé”: went, not “uente”.", ["went", "We went home."]], ["Ravi ___ to the market.", "went", "goed", "Ravi foi ao mercado.", "Go é irregular: o passado é went, não goed."]];
