content[274]=[[["Noah looks at a hotel on his phone.", "O Noah olha um hotel no celular."], ["He wants to know if breakfast is free.", "Ele quer saber se o café da manhã é grátis."], ["Breakfast is free every morning.", "O café da manhã é grátis toda manhã."], ["The pool is open until nine.", "A piscina fica aberta até as nove."], ["Noah is happy and says yes.", "O Noah fica feliz e diz sim."]], [["Is breakfast included?", "O café da manhã está incluído?"], ["Yes, it is. It is free.", "Sim, está. É grátis."], ["Is the pool open now?", "A piscina está aberta agora?"], ["Yes, it is open until nine.", "Sim, fica aberta até as nove."], ["Are towels in the room?", "Há toalhas no quarto?"], ["Yes, they are in the bathroom.", "Sim, estão no banheiro."], ["Is the wifi free too?", "O wifi também é grátis?"], ["Yes, it is free everywhere.", "Sim, é grátis em todo lugar."]], ["Acento em breakfast", "A força fica na primeira sílaba: BREK-fust.", ["breakfast", "Breakfast is free."]], ["___ breakfast included?", "Is", "Are", "O café da manhã está incluído?", "Breakfast é singular, então usamos Is."]];
