content[276]=[[["Ravi is in his hotel room.", "O Ravi está no quarto do hotel."], ["He has no towel and no pillow.", "Ele não tem toalha nem travesseiro."], ["He calls the desk and asks for help.", "Ele liga para a recepção e pede ajuda."], ["A woman brings them in five minutes.", "Uma mulher traz em cinco minutos."], ["Ravi says thank you with a big smile.", "O Ravi agradece com um grande sorriso."]], [["Hello, can you help me?", "Olá, você pode me ajudar?"], ["Yes. What do you need?", "Sim. De que você precisa?"], ["Can you bring a towel, please?", "Pode trazer uma toalha, por favor?"], ["Yes, I can bring two.", "Sim, posso trazer duas."], ["Can you bring a pillow too?", "Pode trazer um travesseiro também?"], ["Of course. I can bring it now.", "Claro. Posso levar agora."], ["Can you bring them to room twelve?", "Pode levar ao quarto doze?"], ["Yes, they are on the way.", "Sim, já estão a caminho."]], ["O z final em please", "Em please o s soa como z: “pliz”, com o i longo.", ["please", "Can you bring it, please?"]], ["___ you bring a towel, please?", "Can", "Do", "Você pode trazer uma toalha, por favor?", "Para pedir um favor usamos Can you + verbo."]];
patterns[276]=new RegExp("\\b[Cc]an you [a-z]+","i");
themes[276]="chat";
