content[277]=[[["Nico is going to fly home tomorrow.", "O Nico vai voar para casa amanhã."], ["He is going to come back next month.", "Ele vai voltar no mês que vem."], ["June is going to meet him next week.", "A June vai encontrá-lo na semana que vem."], ["They are going to have lunch at noon.", "Eles vão almoçar ao meio-dia."], ["Next month, June is going to see his town.", "No mês que vem, a June vai ver a cidade dele."]], [["When are you going to leave?", "Quando você vai partir?"], ["I am going to leave tomorrow.", "Vou partir amanhã."], ["When are you going to come back?", "Quando você vai voltar?"], ["I am going to come back next month.", "Vou voltar no mês que vem."], ["Is June going to meet you?", "A June vai encontrar você?"], ["Yes, she is going to meet me next week.", "Sim, ela vai me encontrar semana que vem."], ["So you are going home tomorrow?", "Então você vai para casa amanhã?"], ["Yes, and I am going to call you.", "Sim, e vou ligar para você."]], ["Acento em tomorrow", "A força cai na segunda sílaba: to-MOR-row.", ["tomorrow", "See you tomorrow."]], ["I am going to leave ___.", "tomorrow", "yesterday", "Vou partir amanhã.", "Com going to usamos tomorrow, não yesterday."]];
patterns[277]=new RegExp("\\b(?:tomorrow|next (?:week|month))\\b","i");
