plans[278]={"title": "No aeroporto", "file": "photo-stationPark-1.webp", "grammar": "At the airport: gate, flight, passport com imperativos", "goal": "Use o verbo na forma base para dar instruções: show, go, wait.", "words": [["gate", "portão"], ["passport", "passaporte"], ["flight", "voo"], ["straight", "em frente"]]};
content[278]=[[["Ben and Tina are at the airport.", "O Ben e a Tina estão no aeroporto."], ["Their flight is at nine.", "O voo deles é às nove."], ["The woman says, “Show your passport, please.”", "A mulher diz: “Mostre seu passaporte, por favor.”"], ["Then they walk to gate twelve.", "Depois eles caminham até o portão doze."], ["They sit near the gate and wait.", "Eles se sentam perto do portão e esperam."]], [["Excuse me, where is gate twelve?", "Com licença, onde fica o portão doze?"], ["Go straight and turn left.", "Siga em frente e vire à esquerda."], ["Is my flight on time?", "O meu voo está no horário?"], ["Yes. Please wait here.", "Sim. Por favor, espere aqui."], ["Do I need my passport?", "Preciso do meu passaporte?"], ["Yes, show your passport at the gate.", "Sim, mostre o passaporte no portão."], ["Is the flight at nine?", "O voo é às nove?"], ["Yes, and please do not be late.", "Sim, e por favor não se atrase."]], ["Acento em passport", "A força fica na primeira sílaba: PASS-port.", ["passport", "Show your passport."]], ["___ your passport, please.", "Show", "Showing", "Mostre seu passaporte, por favor.", "O imperativo usa o verbo na forma base."]];
patterns[278]=new RegExp("\\b(?:Go|Turn|Wait|Show|Sit|Walk|Please wait)\\b|do not be","i");
