content[284]=[[["Ava looks at the calendar on the wall.", "A Ava olha o calendário na parede."], ["This month is March.", "Este mês é março."], ["Her class party is on March fifth.", "A festa da turma dela é no dia cinco de março."], ["Her trip with Noah is on the twentieth.", "A viagem dela com o Noah é no dia vinte."], ["She writes both dates in red.", "Ela escreve as duas datas em vermelho."]], [["What is the date today?", "Qual é a data de hoje?"], ["It is March first.", "É primeiro de março."], ["When is the party?", "Quando é a festa?"], ["It is on March fifth.", "É no dia cinco de março."], ["And when is your trip?", "E quando é a sua viagem?"], ["It is on the twentieth.", "É no dia vinte."], ["Is that this month?", "Isso é neste mês?"], ["Yes, it is. Both dates are in March.", "É, sim. As duas datas são em março."]], ["O som /θ/ em fifth e twentieth", "Termine com a língua entre os dentes e sopre. Pratique devagar: fif-th, twen-ti-eth.", ["fifth", "My party is on March fifth."]], ["My party is on March ___.", "fifth", "five", "Minha festa é no dia cinco de março.", "Em datas, o inglês usa número ordinal: fifth, não five."]];
