content[285]=[[["Today is Ben’s birthday.", "Hoje é o aniversário do Ben."], ["Lia puts seven candles on his cake.", "A Lia põe sete velas no bolo dele."], ["Everyone sings, “Happy birthday to you!”", "Todos cantam: “Parabéns pra você!”"], ["Ben is very happy and blows out the candles.", "O Ben fica muito feliz e apaga as velas."], ["His birthday is in May, so it is a warm day.", "O aniversário dele é em maio, então o dia é quente."]], [["Happy birthday, Ben!", "Feliz aniversário, Ben!"], ["Thank you, Lia. You are kind.", "Obrigado, Lia. Você é gentil."], ["When is your birthday, Lia?", "Quando é o seu aniversário, Lia?"], ["My birthday is on June ninth.", "Meu aniversário é no dia nove de junho."], ["How old are you now, Ben?", "Quantos anos você tem agora, Ben?"], ["I am seven today.", "Hoje eu tenho sete anos."], ["Is the cake for everyone?", "O bolo é para todo mundo?"], ["Yes. Please sing with us!", "É. Cante conosco, por favor!"]], ["Acento em birthday", "A força vai na primeira sílaba: BIRTH-day. O th é com a língua entre os dentes.", ["birthday", "Happy birthday to you."]], ["___ birthday, Ben!", "Happy", "Happy a", "Feliz aniversário, Ben!", "A felicitação fixa é Happy birthday, sem artigo."]];
