content[288]=[[["June has a secret plan for Lou.", "A June tem um plano secreto para o Lou."], ["She buys a ticket because it is his wish.", "Ela compra um ingresso porque é o desejo dele."], ["Lou loves music, so the ticket is a good gift.", "O Lou adora música, então o ingresso é um bom presente."], ["She says nothing because it is a surprise.", "Ela não diz nada porque é uma surpresa."], ["Lou opens the card and smiles.", "O Lou abre o cartão e sorri."]], [["Why do you smile, June?", "Por que você sorri, June?"], ["Because I have a secret.", "Porque eu tenho um segredo."], ["Is it a surprise for Lou?", "É uma surpresa para o Lou?"], ["Yes, it is. He loves music, so I buy a ticket.", "É. Ele adora música, então compro um ingresso."], ["Why not tell him now?", "Por que não contar a ele agora?"], ["Because a surprise is more fun.", "Porque uma surpresa é mais divertida."], ["Is that his wish?", "Esse é o desejo dele?"], ["Yes, he wishes for it every year.", "É, sim. Ele deseja isso todo ano."]], ["Because sem forçar o be", "Diga /bi-KOZ/, com força na segunda sílaba. Na fala rápida muitos dizem só /kəz/.", ["because", "I smile because I am happy."]], ["I buy a ticket ___ he loves music.", "because", "so", "Eu compro um ingresso porque ele adora música.", "Because dá o motivo; so mostra o resultado."]];
patterns[288]=new RegExp("\\b(because|so)\\b","i");
