content[291]=[[["Noah sits at the table with his coffee.", "O Noah está sentado à mesa com o café."], ["He looks sleepy and a little sad.", "Ele parece cansado e um pouco triste."], ["Tina comes and says, “You look serious.”", "A Tina chega e diz: “Você parece sério.”"], ["He says his day is long.", "Ele diz que o dia dele é longo."], ["Then she tells a joke, and he smiles.", "Então ela conta uma piada, e ele sorri."]], [["Noah looks sleepy today.", "O Noah parece cansado hoje."], ["Yes, he works late at night.", "É, ele trabalha até tarde da noite."], ["Does he look sad too?", "Ele parece triste também?"], ["No, he looks happy now.", "Não, ele parece feliz agora."], ["You look serious, Tina.", "Você parece séria, Tina."], ["I am only hungry. I want lunch.", "Estou só com fome. Quero almoçar."], ["Do you want to smile a little?", "Você quer sorrir um pouco?"], ["Yes, I look better with food.", "Quero. Eu fico melhor com comida."]], ["Acento em serious e sleepy", "Em serious a força vai em SE-ri-ous. Em sleepy, a vogal longa: SLEE-py.", ["sleepy", "You look sleepy."]], ["She ___ happy today.", "looks", "looks like", "Ela parece feliz hoje.", "Antes de adjetivo, use só looks, sem like."]];
