content[292]=[[["Ravi has a new teacher.", "O Ravi tem um professor novo."], ["He asks June, “What does he look like?”", "Ele pergunta à June: “Como ele é fisicamente?”"], ["She says, “He has blond hair and a beard.”", "Ela diz: “Ele tem cabelo loiro e barba.”"], ["Ravi asks, “What is he like?”", "O Ravi pergunta: “E como ele é de jeito?”"], ["She says, “He is quiet but very friendly.”", "Ela diz: “Ele é quieto, mas muito simpático.”"]], [["What does your teacher look like?", "Como é o seu professor fisicamente?"], ["He is tall and has blond hair.", "Ele é alto e tem cabelo loiro."], ["Does he have a beard?", "Ele tem barba?"], ["Yes, he has a small beard.", "Tem, sim. Uma barba pequena."], ["What is he like?", "E como ele é de jeito?"], ["He is quiet, but he is friendly.", "Ele é quieto, mas é simpático."], ["Is he strict in class?", "Ele é rígido na aula?"], ["No, he is kind to everyone.", "Não, ele é gentil com todos."]], ["A diferença de acento: look like", "Em What does he look LIKE? a força vai em like. Fale com a voz descendo no fim.", ["blond", "She has blond hair."]], ["What does she ___ like?", "look", "looks", "Como ela é fisicamente?", "Depois de does, o verbo fica na forma base: look."]];
