content[296]=[[["Nico tells a joke at dinner.", "O Nico conta uma piada no jantar."], ["It is really funny, and Peg laughs.", "É muito engraçada, e a Peg ri."], ["Ben says it is quite good.", "O Ben diz que é bem boa."], ["The soup is very hot, so they wait.", "A sopa está muito quente, então eles esperam."], ["Everyone is really happy tonight.", "Todos estão muito felizes hoje à noite."]], [["Is the film funny?", "O filme é engraçado?"], ["Yes, it is really funny.", "É, sim. É muito engraçado."], ["Is it long?", "É longo?"], ["It is quite long, but it is good.", "É bem longo, mas é bom."], ["Is the popcorn good?", "A pipoca está boa?"], ["It is very good and very hot.", "Está muito boa e muito quente."], ["Are you tired?", "Você está cansado?"], ["No, I am really happy.", "Não, estou muito feliz."]], ["O som /w/ em very e really", "Em very, os dentes de cima tocam o lábio de baixo (/v/). Em really, o r vem primeiro: REE-ly.", ["very", "It is very good."]], ["The soup is ___ hot.", "very", "much", "A sopa está muito quente.", "Antes de adjetivo, use very, não much."]];
