plans[299]={"title": "Um dia, uma conversa final", "file": "photo-lake-1.webp", "grammar": "Revisão do A1 em uma conversa final (mini-história)", "goal": "Reúna presente, can, there is/are, adjetivos, perguntas e ligações em uma conversa completa.", "words": [["goodbye", "adeus, tchau"], ["ready", "pronto"], ["together", "juntos"], ["class", "aula"]]};
content[299]=[[["Lia sits by the lake with Ravi.", "A Lia está sentada perto do lago com o Ravi."], ["She says, “This is a very nice place.”", "Ela diz: “Este é um lugar muito bonito.”"], ["They talk about school, food, and music.", "Eles conversam sobre escola, comida e música."], ["Ravi says, “I am ready to go home.”", "O Ravi diz: “Estou pronto para ir para casa.”"], ["They say goodbye and meet again tomorrow.", "Eles se despedem e se encontram de novo amanhã."]], [["Are you ready to go?", "Você está pronto para ir?"], ["Yes, I am. Where do we go?", "Estou. Aonde vamos?"], ["There is a bus stop near the lake.", "Tem um ponto de ônibus perto do lago."], ["Can we ride together?", "Podemos ir juntos?"], ["Sure. What do you do tomorrow?", "Claro. O que você faz amanhã?"], ["I study, and then I cook dinner.", "Eu estudo e depois faço o jantar."], ["Can you come to my house?", "Você pode vir à minha casa?"], ["Yes, I can. Goodbye until tomorrow!", "Posso, sim. Tchau até amanhã!"]], ["Acento em tomorrow e together", "A força vai na segunda sílaba: to-MOR-row, to-GE-ther. Fale com ritmo calmo.", ["together", "We go together."]], ["Are you ___ to go?", "ready", "ready for", "Você está pronto para ir?", "Antes de to + verbo, use ready sem for."]];
patterns[299]=new RegExp("\\b(ready|together|tomorrow|goodbye)\\b","i");
themes[299]="chat";
photos[299]=["photo-lake-1.webp", "photo-friends-1.webp"];
stories[299]=["Lia e a conversa final", "Lia is ready for her last English class.~A Lia está pronta para sua última aula de inglês.|First, she says hello to her teacher.~Primeiro, ela diz oi para a professora.|The teacher asks, “What do you like?”~A professora pergunta: “Do que você gosta?”|Lia answers, “I like music and cake.”~A Lia responde: “Eu gosto de música e bolo.”|There are ten students, and they all clap.~Há dez alunos, e todos batem palmas.|Her friend Ravi is tall, but he is shy.~O amigo dela, o Ravi, é alto, mas é tímido.|Then he asks, “Can we study together?”~Então ele pergunta: “Podemos estudar juntos?”|Lia says yes because she wants a friend.~A Lia diz que sim porque quer um amigo.|After that, they walk to the lake.~Depois disso, eles caminham até o lago.|They say goodbye and meet again tomorrow.~Eles se despedem e se encontram de novo amanhã."];
extras[299]={"goodbye": ["Goodbye, my friend.", "Tchau, meu amigo."]};
plans[300]={"title": "Lavando a roupa de sábado", "file": "photo-counter-1.webp", "grammar": "Presente simples (hábito) vs. presente contínuo (agora)", "goal": "Use o presente simples para o que você faz sempre e am/is/are + verbo-ing para o que acontece agora.", "words": [["wash", "lavar"], ["laundry", "roupa para lavar"], ["soap", "sabão"], ["every Saturday", "todo sábado"]]};
content[300]=[[["Lia washes the laundry every Saturday.", "Lia lava a roupa todo sábado."], ["Today she is washing it with Ben.", "Hoje ela está lavando com o Ben."], ["Ben usually folds the towels.", "O Ben geralmente dobra as toalhas."], ["Now he is folding a big red towel.", "Agora ele está dobrando uma toalha vermelha grande."], ["The whole house smells good.", "A casa inteira está cheirosa."]], [["Do you wash the laundry on Saturday?", "Você lava a roupa no sábado?"], ["Yes, I wash it every Saturday.", "Sim, eu lavo todo sábado."], ["What are you doing now?", "O que você está fazendo agora?"], ["I am washing a blue shirt.", "Estou lavando uma camisa azul."], ["Does Ben help you?", "O Ben ajuda você?"], ["Yes, he usually helps me.", "Sim, ele geralmente me ajuda."], ["Is he helping now?", "Ele está ajudando agora?"], ["Yes, he is holding the towel.", "Sim, ele está segurando a toalha."]], ["O som /ʃ/ em wash", "Una os lábios um pouco e sopre como em “chuva”, sem o t: wash termina em /ʃ/.", ["wash", "I wash my shirt."]], ["Today I ___ the laundry.", "am washing", "wash", "Hoje eu estou lavando a roupa.", "Com “today” e ação em andamento, use am + verbo-ing."]];
patterns[300]=new RegExp("\\b(?:washes|wash|is washing|am washing)\\b","i");
