content[301]=[[["Noah has to take out the trash.", "O Noah tem que levar o lixo para fora."], ["Peg has to vacuum the stairs.", "A Peg tem que passar aspirador na escada."], ["They have to finish before noon.", "Eles têm que terminar antes do meio-dia."], ["Noah does not have to wash dishes.", "O Noah não precisa lavar a louça."], ["He is happy about that.", "Ele está feliz com isso."]], [["What do you have to do today?", "O que você tem que fazer hoje?"], ["I have to vacuum the stairs.", "Eu tenho que passar aspirador na escada."], ["Does Noah have to cook?", "O Noah tem que cozinhar?"], ["No, he has to take out the trash.", "Não, ele tem que levar o lixo para fora."], ["Do you have to finish today?", "Vocês têm que terminar hoje?"], ["Yes, we have to finish before noon.", "Sim, temos que terminar antes do meio-dia."], ["Why before noon?", "Por que antes do meio-dia?"], ["Because Ava has to come at one.", "Porque a Ava tem que vir à uma."]], ["O h em have e has", "Solte um pouco de ar, como um suspiro curto, no começo de have e has.", ["have", "I have to go."]], ["Peg ___ vacuum the bedroom.", "has to", "have to", "A Peg tem que passar aspirador na escada.", "Com he, she ou um nome, use has to."]];
