content[302]=[[["Ravi is cold in the living room.", "O Ravi está com frio na sala."], ["Please close the window, Ben.", "Por favor, feche a janela, Ben."], ["Ben closes it and turns off the fan.", "O Ben fecha e desliga o ventilador."], ["Please turn off the light too.", "Por favor, desligue a luz também."], ["Now the room is warm and quiet.", "Agora a sala está quente e quieta."]], [["Please close the window.", "Por favor, feche a janela."], ["Sure. Is it cold in here?", "Claro. Está frio aqui?"], ["Yes, a little. Please close the door too.", "Sim, um pouco. Feche a porta também, por favor."], ["Okay. Anything else?", "Certo. Mais alguma coisa?"], ["Please turn off the TV.", "Por favor, desligue a TV."], ["Do you want to sleep?", "Você quer dormir?"], ["Yes, I am tired. Please be quiet.", "Sim, estou cansado. Fique quieto, por favor."], ["Of course. Good night!", "Claro. Boa noite!"]], ["O som /z/ em please", "Faça o s vibrar como um zumbido de abelha: pliiz.", ["please", "Please sit here."]], ["___ close the window.", "Please", "Please to", "Por favor, feche a janela.", "No imperativo, use please + verbo, sem to."]];
