content[303]=[[["Tina is moving a heavy box.", "A Tina está carregando uma caixa pesada."], ["Lou sees her at the door.", "O Lou a vê na porta."], ["Can I help you, Tina?", "Posso ajudar você, Tina?"], ["He carries the box upstairs.", "Ele carrega a caixa escada acima."], ["Tina says thank you with a smile.", "A Tina agradece com um sorriso."]], [["Can I help you with the box?", "Posso ajudar você com a caixa?"], ["Yes, please. It is very heavy.", "Sim, por favor. Ela é muito pesada."], ["Can I carry it to the kitchen?", "Posso levar para a cozinha?"], ["No, to the bedroom, please.", "Não, para o quarto, por favor."], ["Can I open the door for you?", "Posso abrir a porta para você?"], ["Thanks, Lou. You are very kind.", "Obrigada, Lou. Você é muito gentil."], ["Can I help you with another box?", "Posso ajudar com outra caixa?"], ["Yes, there is one in the car.", "Sim, tem uma no carro."]], ["Acento em heavy", "Force a primeira sílaba: HE-vy. O ea soa como o e de “pé”.", ["heavy", "The box is heavy."]], ["___ I carry the box?", "Can", "Do", "Posso levar a caixa?", "Para oferecer ajuda, use Can I + verbo."]];
