content[304]=[[["Nico cuts the onions slowly.", "O Nico corta as cebolas devagar."], ["Ava stirs the soup carefully.", "A Ava mexe a sopa com cuidado."], ["The soup is hot, so she works carefully.", "A sopa está quente, então ela trabalha com cuidado."], ["Nico finishes his work quickly.", "O Nico termina o trabalho rapidamente."], ["They cook well together.", "Eles cozinham bem juntos."]], [["Do you cut onions quickly?", "Você corta cebolas rápido?"], ["No, I cut them slowly.", "Não, eu corto devagar."], ["Why slowly?", "Por que devagar?"], ["Because the knife is sharp.", "Porque a faca é afiada."], ["Does Ava cook well?", "A Ava cozinha bem?"], ["Yes, she cooks very well.", "Sim, ela cozinha muito bem."], ["Can you carry the pot carefully?", "Você pode carregar a panela com cuidado?"], ["Sure. It is hot, so I walk slowly.", "Claro. Está quente, então eu ando devagar."]], ["O som /l/ em slowly", "Encoste a ponta da língua atrás dos dentes de cima no s-l-o: slow-ly.", ["slowly", "Walk slowly, please."]], ["Ava stirs the soup ___.", "carefully", "careful", "A Ava mexe a sopa com cuidado.", "Para descrever o verbo, use o advérbio carefully, não o adjetivo careful."]];
