content[305]=[[["June shows Tina how to fold a towel.", "A June mostra à Tina como dobrar uma toalha."], ["First, she puts it on the bed.", "Primeiro, ela a põe sobre a cama."], ["Then she folds it in half.", "Depois ela a dobra ao meio."], ["Tina tries it with a green towel.", "A Tina tenta com uma toalha verde."], ["Now both towels look good.", "Agora as duas toalhas ficam bonitas."]], [["How do you fold a towel?", "Como você dobra uma toalha?"], ["First, I put it on the bed.", "Primeiro, eu a coloco na cama."], ["Then what do you do?", "E depois, o que você faz?"], ["Then I fold it in half.", "Depois eu a dobro ao meio."], ["How do you fold a big towel?", "Como você dobra uma toalha grande?"], ["I fold it in half again.", "Eu a dobro ao meio de novo."], ["How do you put it away?", "Como você a guarda?"], ["I put it on the shelf, flat.", "Eu a ponho na prateleira, plana."]], ["Entonação de How do you…?", "A voz sobe em How e cai no fim da pergunta com palavra de pergunta.", ["fold", "How do you fold it?"]], ["How ___ you fold a towel?", "do", "does", "Como você dobra uma toalha?", "Com you, a pergunta usa do."]];
