content[309]=[[["Lia has to clean the floor today.", "A Lia tem que limpar o chão hoje."], ["She takes the broom and works slowly.", "Ela pega a vassoura e trabalha devagar."], ["There is dust under the sofa.", "Tem poeira embaixo do sofá."], ["Ravi asks, Can I help you?", "O Ravi pergunta: Posso ajudar?"], ["Finally, the floor is clean.", "Finalmente, o chão está limpo."]], [["Do you have to clean the floor?", "Você tem que limpar o chão?"], ["Yes, I have to use the broom.", "Sim, eu tenho que usar a vassoura."], ["Is there much dust?", "Tem muita poeira?"], ["Yes, there is a lot under the sofa.", "Sim, tem muita embaixo do sofá."], ["Can I help you, Lia?", "Posso ajudar você, Lia?"], ["Yes, please. Carry the box carefully.", "Sim, por favor. Carregue a caixa com cuidado."], ["Are you finishing now?", "Você está terminando agora?"], ["Yes, finally. The house is clean.", "Sim, finalmente. A casa está limpa."]], ["O som /ɔː/ em floor", "Arredonde os lábios e alongue o som: floor tem um o longo.", ["floor", "The floor is clean."]], ["Lia ___ clean the floor today.", "has to", "have to", "A Lia tem que limpar o chão hoje.", "Com she ou um nome, use has to."]];
