content[310]=[[["Tina is in a clothing store.", "A Tina está numa loja de roupas."], ["She likes those blue pants on the wall.", "Ela gosta daquela calça azul na parede."], ["How much are those pants?", "Quanto custa aquela calça?"], ["They are forty dollars a pair.", "Custam quarenta dólares o par."], ["These pants are cheaper, so she takes them.", "Esta calça é mais barata, então ela leva."]], [["How much are these pants?", "Quanto custa esta calça?"], ["They are thirty dollars.", "Custa trinta dólares."], ["And how much are those pants?", "E quanto custa aquela calça?"], ["Those are forty dollars a pair.", "Aquela custa quarenta dólares o par."], ["How much is this belt?", "Quanto custa este cinto?"], ["It is ten dollars.", "Custa dez dólares."], ["How much is that hat?", "Quanto custa aquele chapéu?"], ["It is twelve dollars. Do you like it?", "Custa doze dólares. Você gosta dele?"]], ["O th de these e those", "Ponha a língua entre os dentes e vibre a voz: these, those.", ["these", "These are my pants."]], ["How much ___ these pants?", "are", "is", "Quanto custa esta calça?", "Pants e these são plural, então use are."]];
