content[311]=[[["Ben wants a new wallet.", "O Ben quer uma carteira nova."], ["The brown wallet is bigger than the black one.", "A carteira marrom é maior do que a preta."], ["The black one is cheaper than the brown one.", "A preta é mais barata do que a marrom."], ["But the brown one is better.", "Mas a marrom é melhor."], ["Ben pays twenty dollars and goes home.", "O Ben paga vinte dólares e vai para casa."]], [["Is this wallet bigger than that one?", "Esta carteira é maior do que aquela?"], ["Yes, it is bigger and better.", "Sim, é maior e melhor."], ["Is it cheaper than the black one?", "É mais barata do que a preta?"], ["No, the black one is cheaper.", "Não, a preta é mais barata."], ["How much is the black one?", "Quanto custa a preta?"], ["It is fifteen dollars.", "Custa quinze dólares."], ["Is the brown one twenty dollars?", "A marrom custa vinte dólares?"], ["Yes, but it is better than the black one.", "Sim, mas é melhor do que a preta."]], ["O som /ð/ e o fraco de than", "Em than, ponha a língua entre os dentes e fale rápido: /ðən/.", ["than", "Ben is taller than me."]], ["The brown wallet is ___ than the black one.", "bigger", "more big", "A carteira marrom é maior do que a preta.", "Adjetivos curtos fazem o comparativo com -er, sem more."]];
