content[312]=[[["June looks at two bags.", "A June olha duas bolsas."], ["One bag is red and the other is gray.", "Uma bolsa é vermelha e a outra é cinza."], ["Which one do you prefer, Peg?", "Qual você prefere, Peg?"], ["I prefer the gray bag.", "Eu prefiro a bolsa cinza."], ["It looks strong and very light.", "Ela parece forte e bem leve."]], [["Which one do you prefer?", "Qual você prefere?"], ["I prefer the gray bag.", "Eu prefiro a bolsa cinza."], ["Why do you prefer it?", "Por que você a prefere?"], ["It is strong and not heavy.", "É forte e não é pesada."], ["Does June prefer the red one?", "A June prefere a vermelha?"], ["Yes, she prefers red bags.", "Sim, ela prefere bolsas vermelhas."], ["Which one is cheaper?", "Qual é mais barata?"], ["The gray one is twenty-five dollars.", "A cinza custa vinte e cinco dólares."]], ["O som /ɜr/ em prefer", "Acentue a segunda sílaba: pre-FER, com o r forte no final.", ["prefer", "I prefer tea."]], ["I ___ the gray bag.", "prefer", "prefers", "Eu prefiro a bolsa cinza.", "Com I, o verbo fica na forma base: prefer."]];
