content[313]=[[["Noah walks into a small shop.", "O Noah entra numa loja pequena."], ["I am looking for black jeans, he says.", "Estou procurando uma calça jeans preta, ele diz."], ["The clerk shows him a nice pair.", "A vendedora mostra um par bonito."], ["Can I try them on?", "Posso experimentar?"], ["He looks in the mirror and smiles.", "Ele se olha no espelho e sorri."]], [["Hello. Can I help you?", "Olá. Posso ajudar?"], ["Yes, I am looking for jeans.", "Sim, estou procurando uma calça jeans."], ["What color are you looking for?", "Que cor você está procurando?"], ["I am looking for black ones.", "Estou procurando uma preta."], ["Here you are. You can try them on.", "Aqui está. Você pode experimentar."], ["Where is the mirror?", "Onde fica o espelho?"], ["It is next to the door.", "Fica ao lado da porta."], ["Great. They look good on me.", "Ótimo. Ficam bem em mim."]], ["O som /ŋ/ em looking", "Termine looking com o som nasal ng, sem pronunciar g forte.", ["looking", "I am looking for a hat."]], ["I am ___ for black jeans.", "looking", "look", "Estou procurando uma calça jeans preta.", "Para dizer o que está fazendo agora, use am + looking."]];
