content[314]=[[["Lou wants a new T-shirt.", "O Lou quer uma camiseta nova."], ["What size are you?, asks the clerk.", "Que tamanho você usa?, pergunta o vendedor."], ["I am medium, but this one is small.", "Eu sou médio, mas esta é pequena."], ["The blue one comes in large.", "A azul tem em tamanho grande."], ["Lou takes a medium in blue.", "O Lou leva uma média na cor azul."]], [["What size do you need?", "Que tamanho você precisa?"], ["I need a medium, please.", "Preciso de uma média, por favor."], ["What color do you want?", "Que cor você quer?"], ["I want a blue one.", "Quero uma azul."], ["Is this one large?", "Esta é grande?"], ["No, it is small. Here is a large.", "Não, é pequena. Aqui está uma grande."], ["Is the large too big for me?", "A grande é grande demais para mim?"], ["Try the medium. It looks right.", "Experimente a média. Parece certa."]], ["Acento em medium", "Force a primeira sílaba: ME-di-um, com o primeiro e longo.", ["medium", "I wear a medium."]], ["What ___ do you need?", "size", "sizes", "Que tamanho você precisa?", "Depois de what, use size no singular para perguntar um tamanho."]];
