content[315]=[[["Nico is at the counter of a small shop.", "O Nico está no balcão de uma loja pequena."], ["He wants to pay by card.", "Ele quer pagar com cartão."], ["Do you accept cards?, he asks.", "Vocês aceitam cartão?, ele pergunta."], ["No, we only take cash today.", "Não, hoje só aceitamos dinheiro."], ["Nico pays in cash and gets his bag.", "O Nico paga em dinheiro e pega a sacola."]], [["Do you accept cards?", "Vocês aceitam cartão?"], ["No, I am sorry. Only cash.", "Não, sinto muito. Só dinheiro."], ["Do you accept ten-dollar bills?", "Vocês aceitam notas de dez dólares?"], ["Yes, we accept all bills.", "Sim, aceitamos todas as notas."], ["How much is the bag?", "Quanto custa a sacola?"], ["It is eighteen dollars.", "Custa dezoito dólares."], ["Can I pay by card at the bank?", "Posso pagar com cartão no banco?"], ["No, but there is a bank next door.", "Não, mas tem um banco ao lado."]], ["O som /k/ em cash e card", "Solte o ar de uma vez com a parte de trás da língua: k forte.", ["cash", "I pay in cash."]], ["Do you ___ cards?", "accept", "accepts", "Vocês aceitam cartão?", "Depois de do you, o verbo fica na forma base."]];
