content[316]=[[["A customer is waiting in the line.", "Uma cliente está esperando na fila."], ["The clerk is counting the coins.", "A atendente está contando as moedas."], ["Two boys are looking at toys.", "Dois meninos estão olhando brinquedos."], ["A woman is talking on her phone.", "Uma mulher está falando ao telefone."], ["Now the clerk is calling the next customer.", "Agora a atendente está chamando o próximo cliente."]], [["What is the customer doing?", "O que a cliente está fazendo?"], ["She is waiting in the line.", "Ela está esperando na fila."], ["What is the clerk doing?", "O que a atendente está fazendo?"], ["She is counting the coins.", "Ela está contando as moedas."], ["Are the boys buying something?", "Os meninos estão comprando algo?"], ["No, they are only looking.", "Não, eles só estão olhando."], ["Does the clerk count every coin?", "A atendente conta todas as moedas?"], ["Yes, she counts them one by one.", "Sim, ela conta uma por uma."]], ["O -ing em waiting", "Termine com o som nasal ng e sem g forte: wai-ting.", ["waiting", "I am waiting here."]], ["The clerk ___ the coins.", "is counting", "counts", "A atendente está contando as moedas.", "Para uma ação agora, use is + verbo-ing."]];
