content[317]=[[["Ava sees a coat in the window.", "Ava vê um casaco na vitrine."], ["It is too expensive for her.", "É caro demais para ela."], ["Then she sees a sign: Sale today.", "Então ela vê uma placa: Liquidação hoje."], ["Now the coat is only fifty dollars.", "Agora o casaco custa só cinquenta dólares."], ["She has enough money, so she buys it.", "Ela tem dinheiro suficiente, então compra."]], [["Is the coat too expensive?", "O casaco é caro demais?"], ["Yes, it is too expensive today.", "Sim, é caro demais hoje."], ["Do you have enough money?", "Você tem dinheiro suficiente?"], ["No, I have only thirty dollars.", "Não, tenho só trinta dólares."], ["Is this hat cheap enough?", "Este chapéu é barato o suficiente?"], ["Yes, it is twelve dollars.", "Sim, custa doze dólares."], ["Is it too small for you?", "É pequeno demais para você?"], ["No, it is big enough.", "Não, é grande o suficiente."]], ["O som /ʌf/ em enough", "O gh soa como f: e-NUF. Acentue a segunda sílaba.", ["enough", "I have enough money."]], ["The coat is ___ expensive.", "too", "enough", "O casaco é caro demais.", "Too vem antes do adjetivo e enough vem depois; aqui falta too."]];
