content[318]=[[["Ravi likes the new headphones.", "O Ravi gosta dos fones novos."], ["He asks the clerk to show them to him.", "Ele pede ao atendente para mostrá-los."], ["The clerk gives them to Ravi.", "O atendente os entrega ao Ravi."], ["Ravi listens to music with them.", "O Ravi ouve música com eles."], ["They sound great, so he buys them.", "O som é ótimo, então ele os compra."]], [["Can you show me those headphones?", "Pode me mostrar aqueles fones?"], ["Sure. Here are the headphones.", "Claro. Aqui estão os fones."], ["Can I listen to them?", "Posso ouvi-los?"], ["Yes, put them on. Do you like them?", "Sim, ponha. Você gosta deles?"], ["Yes, I like them. How much are they?", "Sim, gosto deles. Quanto custam?"], ["The price is thirty dollars.", "O preço é trinta dólares."], ["Can you give me a box for them?", "Pode me dar uma caixa para eles?"], ["Of course. I will wrap it for you.", "Claro. Vou embrulhar para você."]], ["O som /θ/ em them... e /ð/", "Em them, ponha a língua entre os dentes e vibre a voz: /ðem/.", ["them", "I like them."]], ["I like the headphones. I want to buy ___.", "them", "it", "Eu gosto dos fones. Quero comprá-los.", "Headphones é plural, então o pronome é them."]];
