content[319]=[[["Lia is in a store with Ben.", "A Lia está numa loja com o Ben."], ["She is looking for a new laptop.", "Ela está procurando um notebook novo."], ["The gray laptop is too expensive.", "O notebook cinza é caro demais."], ["The white one is cheaper than the gray one.", "O branco é mais barato do que o cinza."], ["She buys it and says thanks.", "Ela o compra e agradece."]], [["What are you looking for?", "O que você está procurando?"], ["I am looking for a laptop.", "Estou procurando um notebook."], ["How much is this laptop?", "Quanto custa este notebook?"], ["It is four hundred dollars.", "Custa quatrocentos dólares."], ["Is it cheaper than that one?", "É mais barato do que aquele?"], ["Yes, that one is five hundred.", "Sim, aquele custa quinhentos."], ["Do you want to buy it?", "Você quer comprá-lo?"], ["Yes, I will buy it today.", "Sim, vou comprá-lo hoje."]], ["O som /aɪ/ em buy", "Diga “bái”: buy rima com my e tem o u mudo.", ["buy", "I buy a laptop."]], ["The white laptop is ___ than the gray one.", "cheaper", "more cheap", "O notebook branco é mais barato do que o cinza.", "Adjetivos curtos fazem o comparativo com -er."]];
