content[320]=[[["Peg wants to open an account.", "A Peg quer abrir uma conta."], ["There is a small bank near her house.", "Tem um banco pequeno perto da casa dela."], ["There is a clerk at the first desk.", "Tem uma atendente na primeira mesa."], ["Peg shows her passport.", "A Peg mostra o passaporte."], ["She makes a deposit of fifty dollars.", "Ela faz um depósito de cinquenta dólares."]], [["I want to open an account.", "Quero abrir uma conta."], ["Sure. Is there a form to fill?", "Claro. Tem um formulário para preencher?"], ["Yes, there is one on the desk.", "Sim, tem um na mesa."], ["Do you have a passport?", "Você tem passaporte?"], ["Yes, there is one in my bag.", "Sim, tem um na minha bolsa."], ["Do you want to make a deposit?", "Você quer fazer um depósito?"], ["Yes, I want to deposit fifty dollars.", "Sim, quero depositar cinquenta dólares."], ["Great. Your account is open.", "Ótimo. Sua conta está aberta."]], ["Acento em deposit", "Force a segunda sílaba: de-POS-it. O o soa como /ɑ/.", ["deposit", "I make a deposit."]], ["There ___ a bank near my house.", "is", "are", "Tem um banco perto da minha casa.", "Bank é singular, então use there is."]];
