content[321]=[[["June wants to send a letter to Brazil.", "A June quer enviar uma carta para o Brasil."], ["She goes to the mail office.", "Ela vai ao correio."], ["How much is it to send this letter?", "Quanto custa enviar esta carta?"], ["How long does it take?", "Quanto tempo leva?"], ["It takes one week, the clerk says.", "Leva uma semana, diz o atendente."]], [["I want to send this letter to Brazil.", "Quero enviar esta carta para o Brasil."], ["Okay. Write the address here.", "Certo. Escreva o endereço aqui."], ["And how much is it to Brazil?", "E quanto custa para o Brasil?"], ["Letters to Brazil are two dollars.", "Cartas para o Brasil custam dois dólares."], ["How long does it take?", "Quanto tempo leva?"], ["It takes about one week.", "Leva cerca de uma semana."], ["Can I send it today?", "Posso enviar hoje?"], ["Yes, the mail leaves at four.", "Sim, o correio sai às quatro."]], ["O som /æ/ em address", "Abra bem a boca no primeiro a: a-DRESS, com acento na segunda sílaba.", ["address", "Write your address."]], ["How ___ does it take?", "long", "much", "Quanto tempo leva?", "Para perguntar o tempo, use how long; how much é para preço."]];
