content[322]=[[["Noah goes to the library after school.", "O Noah vai à biblioteca depois da escola."], ["It is quiet, and many people are reading.", "Está silencioso, e muita gente está lendo."], ["Can I borrow this magazine?", "Posso pegar esta revista emprestada?"], ["Yes, but return it by Friday.", "Sim, mas devolva até sexta."], ["He wants to read it at home.", "Ele quer lê-la em casa."]], [["Can I borrow this magazine?", "Posso pegar esta revista emprestada?"], ["Yes. Please show me your card.", "Sim. Mostre seu cartão, por favor."], ["Here it is. When is it due?", "Aqui está. Quando vence?"], ["The due date is next Friday.", "A data de devolução é sexta que vem."], ["Can I return it at the desk?", "Posso devolver no balcão?"], ["Yes, put it on the desk.", "Sim, deixe no balcão."], ["Can I borrow two magazines?", "Posso pegar duas revistas?"], ["Yes, you can borrow three.", "Sim, você pode pegar três."]], ["O som /ʌ/ em due... e library", "Em library, acentue a primeira sílaba: LI-bra-ry.", ["library", "I go to the library."]], ["Can I ___ this magazine?", "borrow", "lend", "Posso pegar esta revista emprestada?", "Quem pede emprestado usa borrow; lend é quem empresta."]];
