content[323]=[[["The bank closes at five in the evening.", "O banco fecha às cinco da tarde."], ["The post office opens at nine in the morning.", "O correio abre às nove da manhã."], ["On Friday, Tina goes to the bank.", "Na sexta, a Tina vai ao banco."], ["In July, she wants to travel.", "Em julho, ela quer viajar."], ["She finishes her letter at midnight.", "Ela termina a carta à meia-noite."]], [["What time does the bank close?", "A que horas o banco fecha?"], ["It closes at five in the evening.", "Fecha às cinco da tarde."], ["What day do you go there?", "Em que dia você vai lá?"], ["I go on Friday.", "Eu vou na sexta."], ["When do you want to travel?", "Quando você quer viajar?"], ["I want to travel in July.", "Quero viajar em julho."], ["Do you work at midnight?", "Você trabalha à meia-noite?"], ["No, I sleep at midnight.", "Não, eu durmo à meia-noite."]], ["O som /ɪ/ em in", "Mantenha o i curto, como em “início”, sem esticar: in, it, is.", ["evening", "I sleep in the evening."]], ["I go to the bank ___ Friday.", "on", "at", "Eu vou ao banco na sexta.", "Para dias da semana, use on."]];
