content[325]=[[["Ravi wants a book about trains.", "Ravi quer um livro sobre trens."], ["He walks to the library after lunch.", "Ele vai à biblioteca depois do almoço."], ["A sign shows the hours of the library.", "Um aviso mostra o horário da biblioteca."], ["The woman says the library closes at eight.", "A mulher diz que a biblioteca fecha às oito."], ["Ravi gets a pen and finds a book.", "Ravi pega uma caneta e acha um livro."]], [["What time does the library open?", "A que horas a biblioteca abre?"], ["It opens at nine in the morning.", "Abre às nove da manhã."], ["When does it close today?", "Quando ela fecha hoje?"], ["It closes at eight tonight.", "Ela fecha às oito da noite."], ["What time do I return the book?", "A que horas devolvo o livro?"], ["Please bring it back by five.", "Traga de volta até as cinco."], ["When does the children room open?", "Quando abre a sala das crianças?"], ["It opens at ten on Saturday.", "Abre às dez no sábado."]], ["/w/ em What e When", "Arredonde os lábios como em u e abra rápido para o som seguinte.", ["what", "What time is it?"]], ["___ does the library close?", "When", "Where", "Quando a biblioteca fecha?", "Para perguntar sobre o momento, usamos When ou What time."]];
