content[326]=[[["Tina is new in the city.", "Tina é nova na cidade."], ["She needs a toilet before the bus.", "Ela precisa de um banheiro antes do ônibus."], ["A man says, \"Go straight, then turn left.\"", "Um homem diz: \"Siga em frente e vire à esquerda.\""], ["The toilet is behind the post office.", "O banheiro fica atrás do correio."], ["Then Tina finds her bus stop.", "Depois Tina acha seu ponto de ônibus."]], [["Excuse me, where is the toilet?", "Com licença, onde fica o banheiro?"], ["It is behind the post office.", "Fica atrás do correio."], ["Is there a bus stop near here?", "Tem um ponto de ônibus por aqui?"], ["Yes, go straight for two blocks.", "Sim, siga em frente por duas quadras."], ["Excuse me, where is Main Street?", "Com licença, onde fica a Main Street?"], ["Turn left at the corner.", "Vire à esquerda na esquina."], ["Is there a bank on that street?", "Tem um banco naquela rua?"], ["Yes, it is next to the bakery.", "Sim, fica ao lado da padaria."]], ["Entonação em Excuse me", "Comece com o tom médio e suba um pouco no fim de Excuse me para soar educado.", ["excuse", "Excuse me, please."]], ["Excuse me, ___ the toilet?", "where is", "where are", "Com licença, onde fica o banheiro?", "Toilet está no singular, então usamos where is."]];
