content[329]=[[["Lou has four jobs to do this morning.", "Lou tem quatro tarefas para fazer nesta manhã."], ["First, he needs a stamp for an envelope.", "Primeiro, ele precisa de um selo para um envelope."], ["Excuse me, where is the post office?", "Com licença, onde fica o correio?"], ["It is next to the library.", "Fica ao lado da biblioteca."], ["Lou waits in line for ten minutes.", "Lou espera na fila por dez minutos."]], [["What time does the post office open?", "A que horas o correio abre?"], ["It opens at nine every day.", "Abre às nove todo dia."], ["Is there a line at the desk?", "Tem fila no balcão?"], ["Yes, but it is short today.", "Tem, mas está curta hoje."], ["How much is one stamp?", "Quanto custa um selo?"], ["It is sixty cents.", "Custa sessenta centavos."], ["When does the mail go out?", "Quando sai a correspondência?"], ["It goes out at four o’clock.", "Sai às quatro horas."]], ["Som de st em stamp", "Diga s e t juntos, sem vogal antes: stamp, não estamp.", ["stamp", "One stamp, please."]], ["The mail ___ at four o’clock.", "goes out", "go out", "A correspondência sai às quatro horas.", "Mail é singular, então o verbo leva -es."]];
