content[330]=[[["Ava has a free Sunday.", "Ava tem um domingo livre."], ["She wants to invite Nico to the lake.", "Ela quer convidar Nico para ir ao lago."], ["Nico says, \"Yes, I would.\"", "Nico diz: \"Sim, eu gostaria.\""], ["Ava asks Ben to join them too.", "Ava pede que Ben se junte a eles também."], ["Ben says no, thank you, because he works.", "Ben diz que não, obrigado, porque trabalha."]], [["Would you like to join us on Sunday?", "Você gostaria de se juntar a nós no domingo?"], ["Yes, I would. Where are you going?", "Sim, gostaria. Aonde vocês vão?"], ["We are going to the lake.", "Vamos ao lago."], ["Would you like to bring lemonade?", "Você gostaria de levar limonada?"], ["Yes, I would. I have apples.", "Sim, gostaria. Eu tenho maçãs."], ["Would you like to sit on the bench?", "Você gostaria de sentar no banco?"], ["No, thank you. I like the grass.", "Não, obrigado. Eu gosto da grama."], ["Would you like to invite Ben too?", "Você gostaria de convidar o Ben também?"]], ["Would you", "Junte would e you num som só: woodjoo.", ["would", "Would you like tea?"]], ["___ you like to join us?", "Would", "Do", "Você gostaria de se juntar a nós?", "Para convite cortês usamos Would you like to."]];
