content[331]=[[["Noah and Tina are going camping this weekend.", "Noah e Tina vão acampar neste fim de semana."], ["They are going to put up a tent by the water.", "Eles vão armar uma barraca perto da água."], ["Tina is going to bring a lantern.", "Tina vai levar uma lanterna."], ["Noah is going to make a small fire.", "Noah vai fazer uma pequena fogueira."], ["They are not going to sleep late.", "Eles não vão dormir até tarde."]], [["What are you going to do on Saturday?", "O que você vai fazer no sábado?"], ["I am going camping with Noah.", "Vou acampar com o Noah."], ["Are you going to take a tent?", "Você vai levar uma barraca?"], ["Yes, we are going to use a blue one.", "Sim, vamos usar uma azul."], ["Who is going to bring the food?", "Quem vai levar a comida?"], ["I am going to cook rice and fish.", "Eu vou cozinhar arroz e peixe."], ["Is it going to rain?", "Vai chover?"], ["No, it is going to be sunny.", "Não, vai fazer sol."]], ["Going to rápido", "Na fala natural, going to vira algo como gonna, mas escreva por extenso.", ["going", "I am going to swim."]], ["We ___ going to camp by the lake.", "are", "is", "Nós vamos acampar perto do lago.", "Com we, o verbo be correto é are."]];
