content[332]=[[["Peg and Lou are at the cinema.", "Peg e Lou estão no cinema."], ["The movie starts at seven.", "O filme começa às sete."], ["There are two seats in row F.", "Há dois assentos na fileira F."], ["Lou buys popcorn for the show.", "Lou compra pipoca para a sessão."], ["There is a big screen in front of them.", "Há uma tela grande na frente deles."]], [["Two tickets for the seven o’clock movie, please.", "Dois ingressos para o filme das sete, por favor."], ["There are two seats in row F.", "Há dois assentos na fileira F."], ["What time does the movie start?", "A que horas o filme começa?"], ["It starts at seven ten.", "Começa às sete e dez."], ["Is there popcorn here?", "Tem pipoca aqui?"], ["Yes, there is a small stand.", "Tem, há uma barraquinha."], ["Is there a seat near the door?", "Tem um assento perto da porta?"], ["Yes, there are two in row A.", "Sim, há dois na fileira A."]], ["Movie e seven", "Em movie, o acento está na primeira sílaba: MOO-vee.", ["movie", "The movie is long."]], ["___ two seats in row F.", "There are", "There is", "Há dois assentos na fileira F.", "Two seats é plural, então usamos There are."]];
