content[337]=[[["Last Saturday Tina went to a town fair.", "No sábado passado Tina foi a uma feira da cidade."], ["She watched a parade in the square.", "Ela assistiu a um desfile na praça."], ["A big crowd clapped for the dancers.", "Uma grande multidão aplaudiu os dançarinos."], ["Tina ate corn and drank cold juice.", "Tina comeu milho e bebeu suco gelado."], ["At night she saw fireworks over the lake.", "À noite ela viu fogos de artifício sobre o lago."]], [["Where did you go on Saturday?", "Aonde você foi no sábado?"], ["I went to the town fair.", "Fui à feira da cidade."], ["Did you see the parade?", "Você viu o desfile?"], ["Yes, I saw it with Lou.", "Vi, com o Lou."], ["What did you eat there?", "O que você comeu lá?"], ["I ate corn and a big cookie.", "Comi milho e um biscoito grande."], ["Did you stay for the fireworks?", "Você ficou para os fogos?"], ["Yes, I stayed until ten.", "Sim, fiquei até as dez."]], ["-ed no passado", "Depois de som surdo, -ed soa como t: watched. Depois de som sonoro, soa d.", ["watched", "She watched the parade."]], ["Tina ___ a parade last Saturday.", "watched", "watch", "A Tina assistiu a um desfile no sábado passado.", "Com last Saturday usamos o passado: watched."]];
