content[339]=[[["Ben has a busy weekend with his friends.", "Ben tem um fim de semana cheio com os amigos."], ["Ava invites him to a boat trip on Saturday.", "Ava convida Ben para um passeio de barco no sábado."], ["They watch the sunset from the boat.", "Eles veem o pôr do sol do barco."], ["Ben takes many photos with his camera.", "Ben tira muitas fotos com sua câmera."], ["On Sunday he is going to sleep late.", "No domingo ele vai dormir até tarde."]], [["Would you like to join the boat trip?", "Você gostaria de participar do passeio de barco?"], ["Yes, I would. When does it start?", "Sim, gostaria. Quando começa?"], ["It starts at five on Saturday.", "Começa às cinco no sábado."], ["Can I take my camera?", "Posso levar minha câmera?"], ["Yes, you can take photos there.", "Sim, você pode tirar fotos lá."], ["What are you going to do on Sunday?", "O que você vai fazer no domingo?"], ["I am going to rest, because I am tired.", "Vou descansar, porque estou cansado."], ["Did you like the boat?", "Você gostou do barco?"]], ["Rest e wet", "O e é aberto, como em pé; termine com t leve.", ["rest", "I rest on Sunday."]], ["I am tired, ___ I am going to rest.", "so", "because", "Estou cansado, então vou descansar.", "So mostra o resultado; because daria o motivo."]];
