content[340]=[[["Lou runs a small quiz at school.", "Lou comanda um pequeno quiz na escola."], ["He asks, \"What is the weather like in Brazil?\"", "Ele pergunta: \"Como é o clima no Brasil?\""], ["Ava knows the country and the capital.", "Ava conhece o país e a capital."], ["Noah asks why people speak Portuguese there.", "Noah pergunta por que as pessoas falam português lá."], ["Lou smiles, because the class loves quizzes.", "Lou sorri, porque a turma adora quizzes."]], [["Who knows this country?", "Quem conhece este país?"], ["I do. It is Brazil.", "Eu conheço. É o Brasil."], ["Where is the capital?", "Onde fica a capital?"], ["It is in the middle of the country.", "Fica no meio do país."], ["What language do they speak?", "Que idioma eles falam?"], ["They speak Portuguese.", "Eles falam português."], ["How is the weather there?", "Como está o clima lá?"], ["It is warm and sunny.", "É quente e ensolarado."]], ["Why e where", "Em why use o w arredondado; em where, o h não soa.", ["where", "Where is the weather map?"]], ["___ is the capital?", "Where", "Who", "Onde fica a capital?", "Para lugar usamos where."]];
