content[341]=[[["Today Ben is nervous about his test.", "Hoje Ben está nervoso com a prova."], ["His sister is calm and happy.", "A irmã dele está calma e feliz."], ["She says, \"You are not alone.\"", "Ela diz: \"Você não está sozinho.\""], ["Ben is not angry, he is only afraid.", "Ben não está bravo, só com medo."], ["Now they are both at the school gate.", "Agora os dois estão no portão da escola."]], [["Are you nervous today?", "Você está nervoso hoje?"], ["Yes, I am. I am a little afraid.", "Estou, sim. Estou com um pouco de medo."], ["Is your sister angry?", "Sua irmã está brava?"], ["No, she is not angry. She is calm.", "Não, ela não está brava. Está calma."], ["Are we late for class?", "Estamos atrasados para a aula?"], ["No, we are not late.", "Não, não estamos atrasados."], ["Is the teacher happy today?", "A professora está feliz hoje?"], ["Yes, she is very happy.", "Sim, ela está muito feliz."]], ["Am, is, are", "Am e are são fracos na frase; is é curto. Fale rápido: I am, she is.", ["happy", "I am happy."]], ["She ___ not angry.", "is", "are", "Ela não está brava.", "Com she usamos is."]];
