content[348]=[[["Lia wants a new bag for school.", "Lia quer uma mochila nova para a escola."], ["The red bag is bigger, but it is heavier.", "A mochila vermelha é maior, mas é mais pesada."], ["The green bag is cheaper than the red one.", "A mochila verde é mais barata que a vermelha."], ["The black bag is the most expensive.", "A mochila preta é a mais cara."], ["Lia takes the cheapest bag and goes home.", "Lia leva a mochila mais barata e vai para casa."]], [["Is the red bag bigger than the blue one?", "A mochila vermelha é maior que a azul?"], ["Yes, it is bigger, but it is heavy.", "Sim, é maior, mas é pesada."], ["Which bag is the cheapest?", "Qual mochila é a mais barata?"], ["The green one is the cheapest.", "A verde é a mais barata."], ["Is the black bag more expensive?", "A preta é mais cara?"], ["Yes, it is the most expensive.", "Sim, é a mais cara."], ["Is this line slower than that one?", "Esta fila é mais lenta que aquela?"], ["Yes, it is much slower.", "Sim, é bem mais lenta."]], ["Than e the", "O th de than e the é suave, com a língua entre os dentes.", ["than", "This bag is bigger than that one."]], ["The green bag is ___ than the red one.", "cheaper", "more cheap", "A mochila verde é mais barata que a vermelha.", "Adjetivo curto forma o comparativo com -er."]];
